var regions={quad:["大腿前面",108,"+8",70,12,59],calf:["ふくらはぎ",103,"+3",57.5,28,78],glute:["殿部",101,"+1",52.5,24,50],foot:["足部",98,"-2",45,28,91],ham:["大腿後面",104,"+4",60,28,59],shin:["下腿前面",102,"+2",55,12,78],hip:["股関節周辺",100,"0",50,20,48],trunk:["体幹",99,"-1",47.5,17,31],shoulder:["肩周辺",97,"-3",42.5,6,28],arm:["上腕",96,"-4",40,3,43],ankle:["足関節周辺",101,"+1",52.5,28,86],whole:["全身",100,"0",50,16,42]};
function setRegion(k){var r=regions[k];if(!r)return;document.querySelector("#regionName").textContent=r[0];document.querySelector("#refValue").textContent=r[1];document.querySelector("#refDiff").textContent="基準100より "+(r[2]==="0"?"±0":r[2]);document.querySelector("#markerVal").textContent=r[1];document.querySelector("#marker").style.left=r[3]+"%";document.querySelector("#pulse").style.left=r[4]+"px";document.querySelector("#pulse").style.top=r[5]+"px";document.querySelectorAll(".chip").forEach(function(b){b.classList.toggle("on",b.dataset.key===k)})}
document.querySelectorAll(".chip").forEach(function(b){b.addEventListener("click",function(){setRegion(b.dataset.key)})});
function toggle(btn,panel){document.querySelector(btn).addEventListener("click",function(){var p=document.querySelector(panel);p.hidden=!p.hidden})}toggle("#factsToggle","#factsPanel");toggle("#scienceToggle","#sciencePanel");
function openModal(id){document.querySelector("#"+id).hidden=false;document.body.style.overflow="hidden"}function closeModal(id){document.querySelector("#"+id).hidden=true;document.body.style.overflow=""}
document.querySelector("#allRegions").onclick=function(){openModal("regionModal")};document.querySelector("#themeBtn").onclick=function(){openModal("themeModal")};document.querySelectorAll("[data-close]").forEach(function(b){b.onclick=function(){closeModal(b.dataset.close)}});document.querySelectorAll(".overlay").forEach(function(o){o.addEventListener("click",function(e){if(e.target===o)closeModal(o.id)})});
var order=["quad","ham","glute","hip","calf","shin","ankle","foot","trunk","shoulder","arm","whole"],grid=document.querySelector("#regionGrid");order.forEach(function(k){var r=regions[k],b=document.createElement("button");b.innerHTML="<strong>"+r[0]+"</strong><span>Reference-100 "+r[1]+"</span>";b.onclick=function(){setRegion(k);closeModal("regionModal")};grid.appendChild(b)});
var applied="default",preview="default";function setTheme(t){preview=t;document.documentElement.dataset.theme=t;document.querySelectorAll(".theme-option").forEach(function(b){b.classList.toggle("on",b.dataset.theme===t)})}document.querySelectorAll(".theme-option").forEach(function(b){b.onclick=function(){setTheme(b.dataset.theme)}});document.querySelector("#applyTheme").onclick=function(){applied=preview;closeModal("themeModal")};document.querySelector("#cancelTheme").onclick=function(){setTheme(applied);closeModal("themeModal")};